// Single-file launcher for Graffiti Pad.
//
// The whole portable app (GraffitiPad.exe plus its app\ and runtime\ folders) is embedded in
// this exe as the resource "app.zip". On first run it is unpacked to
// %LOCALAPPDATA%\GraffitiPad\app-<build id>\ and started from there; later runs start it
// straight away. Unpacked copies of older builds are cleaned up.
//
// Compiled with the C# 5 compiler in .NET Framework 4 (present on every Windows 10/11 PC),
// by the Gradle task packageSingleExe. BuildInfo.Id is generated by that task.
using System;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Windows.Forms;

static class Launcher
{
    const string Marker = ".unpacked";

    [STAThread]
    static int Main(string[] args)
    {
        try
        {
            string root = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "GraffitiPad");
            string dir = Path.Combine(root, "app-" + BuildInfo.Id);
            string exe = Path.Combine(dir, "GraffitiPad", "GraffitiPad.exe");

            if (!File.Exists(Path.Combine(dir, Marker)) || !File.Exists(exe))
            {
                Unpack(root, dir);
                CleanOld(root, dir);
            }

            var psi = new ProcessStartInfo(exe);
            psi.UseShellExecute = false;
            psi.WorkingDirectory = Path.GetDirectoryName(exe);
            psi.Arguments = JoinArgs(args);
            Process.Start(psi);
            return 0;
        }
        catch (Exception e)
        {
            MessageBox.Show("Graffiti Pad could not start:\n\n" + e.Message, "Graffiti Pad",
                MessageBoxButtons.OK, MessageBoxIcon.Error);
            return 1;
        }
    }

    // Unpacks into a temporary sibling folder, then renames it into place, so a run that is
    // interrupted halfway never leaves a broken copy that looks complete.
    static void Unpack(string root, string dir)
    {
        Directory.CreateDirectory(root);
        string tmp = dir + ".tmp-" + Process.GetCurrentProcess().Id;
        if (Directory.Exists(tmp)) Directory.Delete(tmp, true);
        using (Stream s = Assembly.GetExecutingAssembly().GetManifestResourceStream("app.zip"))
        using (var zip = new ZipArchive(s, ZipArchiveMode.Read))
        {
            zip.ExtractToDirectory(tmp);
        }
        File.WriteAllText(Path.Combine(tmp, Marker), BuildInfo.Id);
        if (Directory.Exists(dir)) Directory.Delete(dir, true);
        try
        {
            Directory.Move(tmp, dir);
        }
        catch (IOException)
        {
            // Another copy of the launcher finished unpacking first; use that one.
            if (!File.Exists(Path.Combine(dir, Marker))) throw;
            Directory.Delete(tmp, true);
        }
    }

    // Removes unpacked copies of other builds. Best effort: one that is still running is
    // locked and simply skipped until next time.
    static void CleanOld(string root, string keep)
    {
        foreach (string d in Directory.GetDirectories(root, "app-*"))
        {
            if (string.Equals(d, keep, StringComparison.OrdinalIgnoreCase)) continue;
            try { Directory.Delete(d, true); } catch (Exception) { }
        }
    }

    static string JoinArgs(string[] args)
    {
        var parts = new string[args.Length];
        for (int i = 0; i < args.Length; i++)
            parts[i] = "\"" + args[i].Replace("\"", "\\\"") + "\"";
        return string.Join(" ", parts);
    }
}
